#!/usr/bin/env bash
# Sync the canonical skill into the Codex marketplace copy.
#
# Codex bundles only files inside the plugin subdirectory: symlinks and
# ../ escapes are silently dropped. So plugins/persian-colloquial/skills/
# holds a real copy of skills/persian-colloquial/, regenerated by this
# script. Never edit the copy by hand; run this after any skill change.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="$ROOT/skills/persian-colloquial"
DST="$ROOT/plugins/persian-colloquial/skills/persian-colloquial"

rm -rf "$DST"
mkdir -p "$DST"
cp -r "$SRC"/. "$DST"/
echo "Synced $SRC -> $DST"
